#!/bin/sh
# Name: ZenOS
# Author: ZenLabs
# Icon: data:image/png;base64,
# DontUseFBInk
# Version: 1.1.1

# Framework shutdown can also send SIGTERM to this launcher.
trap ':' TERM
if [ -d /mnt/us/extensions/kual ]; then
    /mnt/us/koreader/koreader.sh --kual --framework_stop
else
    /mnt/us/koreader/koreader.sh --framework_stop
fi
koreader_status=$?
# Recover the Kindle UI if KOReader returned without starting it.
if [ -d /etc/upstart ] && ! status lab126_gui | grep -q 'start/'; then
    (cd / && start lab126_gui)
fi
exit "$koreader_status"
